-- =====================================================================
-- Locale_410.lua — v4.1.0 release notes
-- =====================================================================

TomoMod_RegisterLocale("enUS", {
    ["wn_410_bags_money"] = "Fixed — Bags now display gold, silver and copper with coin icons using the current currency API, instead of showing the raw copper total when the legacy formatter is unavailable.",
    ["wn_410_loots_devourer"] = "Fixed — Devourer is now available alongside Havoc and Vengeance in the Loots Demon Hunter specialization selector, using the existing specialization loot filters.",
    ["wn_410_loots_filters"] = "New — Loots remembers an equipment-slot filter across dungeons, raids and favorites. Equipped items show a green check mark; Ctrl-click tries an item on, Shift-click inserts its link into active chat, and left- or right-click toggles a favorite.",
    ["wn_410_loots_kithix"] = "New — Kith'ix's loot table includes 12 items in Raid Finder, Normal and Heroic, plus one extra Mythic collectible, with class/spec filters and the boss's rank-3 upgrade bonuses.",
    ["wn_410_loots_levels"] = "Fixed — Raid item links now use Season 17 bonuses and item-level adjustments. Dungeons have a saved M0 / M+2–M+10 selector for end-of-dungeon rewards, with immediate refresh. Favorites keep their saved upgrade bonus.",
    ["loots_all_slots"] = "All equipment slots",
    ["loots_equipped"] = "Already equipped; upgrade level may differ",
    ["loots_click_help"] = "Click: favorite · Shift-click: chat · Ctrl-click: try on",
    ["wn_410_character_gems"] = "Fixed — CharacterSkin now reads gems through the modern item APIs, preventing an initialization error when GetItemGem is unavailable. Character and inspect frames retain legacy compatibility and handle missing gem details or optional APIs safely.",
    ["wn_410_minimap_tracking"] = "Changed — The custom tracking menu now uses two columns, bordered rows, a darker background, larger icons and cyan indicators for active filters. Available filters and merged duplicate entries are preserved; long lists remain scrollable.",
    ["wn_410_minimap_coords"] = "Fixed — Blizzard's native minimap coordinates are hidden while the TomoMod InfoPanel is enabled, preventing duplicate coordinates from overlapping the clock, even when Blizzard tries to show them again.",
    ["wn_410_benchmark_native_dps"] = "Changed — Benchmark tests now capture the current combat session’s native average DPS at 30/60/120 seconds, using the latest sample if no fresh update arrives after a short wait. Total damage is no longer displayed.",
    ["wn_410_benchmark_protected_history"] = "New — Protected DPS stays visible until reload. Attempt details are saved without the protected number; recent protected attempts appear above ranked results with an asterisk and show Protected after reload.",
    ["wn_410_benchmark_cancellation"] = "Fixed — Tests are cancelled if combat ends early or the meter is reset. Missing native DPS is reported instead of showing a false zero.",
    ["wn_410_window_fit"] = "Fixed — The options window adapts its size and resize limits to the screen and interface scale, keeping the footer and resize handle accessible. Duplicate page headers were removed to free up space.",
    ["wn_410_readability"] = "Changed — Secondary text, hints and search results have stronger contrast, with larger text in several controls and dashboard cards.",
    ["wn_410_home_resets"] = "Changed — Home puts Studios directly below the summary and keeps Installer and Reload as quick actions. Full reset is now available only in Profiles > Resets; module resets use red buttons and ask for confirmation with backup recovery instructions.",
    ["wn_410_automation_movers"] = "Changed — Automation switches now describe their action explicitly, and the secondary status-bar explanation appears on hover. Obsolete bag and World Quest mover routes were removed; Bags V4 remains the movable bag window.",
    ["wn_410_sidebar"] = "New — The sidebar keeps all main sections visible, expands Interface and Comfort pages in place and provides direct access to each Studio. Navigation preserves its scroll position; search also reveals matching subpages.",
    ["wn_410_studio_routing"] = "Changed — Legacy settings panels are retired. Home shortcuts, role recommendations and old settings links now open the appropriate Studio. Unknown pages return to Home; Blizzard Cooldown Manager styling remains under Interface.",
    ["wn_410_nameplate_controls"] = "New — Astral Forge now includes nameplate raid marker size and interruptible or uninterruptible castbar colors, moved from the retired Nameplates panel.",
    ["wn_410_search"] = "New — Settings search now indexes pages and controls in Astral Forge, Party & Raid Studio and Resource & Cast Studio. Results open the matching subject and section, scroll to the setting and highlight it; English search terms are also supported on localized clients.",
    ["wn_410_navigation"] = "Fixed — Interface and Comfort navigation hide pages unavailable on the current client, remove empty groups and safely handle remembered pages.",
    ["wn_410_help"] = "Changed — The help guide now explains search across options and Studios, page tabs and direct Studio access. The obsolete role-filter step has been removed.",
    ["wn_410_localization"] = "New — Shared anchor labels and more interface text are localized in six languages: action bars, audio channels, backups, module resets, dashboard status and CVar tooltips.",
    ["wn_410_studios"] = "Fixed — Studio launch errors and recovery instructions are localized. Incorrect role badges were removed from Astral Forge, Party & Raid and Resource & Cast section headers.",
    ["wn_410_sliders"] = "Changed — Slider tooltips distinguish resetting to a default from restoring the value present when the page opened. English Bloodlust sound labels and dashboard wording were corrected.",
    ["wn_410_role_links"] = "Changed — Role recommendations now open the relevant Studio section directly and highlight the target setting. Sidebar role filters and the role-focus action have been removed; the Roles guides remain available.",
    ["wn_410_search_groups"] = "New — Option-group labels are searchable, making groups such as Auto Summon easier to find. Studio results display their page path and avoid duplicate entries.",
})

TomoMod_RegisterLocale("frFR", {
    ["wn_410_bags_money"] = "Correction — Les sacs affichent désormais les pièces d’or, d’argent et de cuivre avec leurs icônes via l’API actuelle, au lieu du total brut en cuivre lorsque l’ancienne fonction de formatage est indisponible.",
    ["wn_410_loots_devourer"] = "Correction — Dévoration est désormais disponible avec Dévastation et Vengeance dans le sélecteur de spécialisations du chasseur de démons de Loots, avec les filtres de butin par spécialisation existants.",
    ["wn_410_loots_filters"] = "Nouveauté — Loots mémorise un filtre par emplacement pour les donjons, raids et favoris. Une coche verte signale les objets équipés ; Ctrl-clic permet l’essayage, Maj-clic insère le lien dans la discussion active et un clic gauche ou droit bascule le favori.",
    ["wn_410_loots_kithix"] = "Nouveauté — La table de Kith’ix comprend 12 objets en outil Raids, Normal et Héroïque, plus un objet de collection supplémentaire en Mythique, avec les filtres classe/spécialisation et les bonus d’amélioration de rang 3 du boss.",
    ["wn_410_loots_levels"] = "Correction — Les liens de butin de raid utilisent les bonus de la saison actuelle et l’ajustement de niveau d’objet. Les donjons disposent d’un sélecteur M0 / M+2–M+10 mémorisé pour le butin de fin de donjon, avec actualisation immédiate. Les favoris conservent leur bonus enregistré.",
    ["loots_all_slots"] = "Tous les emplacements",
    ["loots_equipped"] = "Déjà équipé ; le niveau d’amélioration peut différer",
    ["loots_click_help"] = "Clic : favori · Maj-clic : discussion · Ctrl-clic : essayer",
    ["wn_410_character_gems"] = "Correction — CharacterSkin utilise désormais les API modernes pour lire les gemmes, évitant une erreur d’initialisation lorsque GetItemGem est indisponible. Les fiches de personnage et d’inspection restent compatibles avec les anciens clients et gèrent l’absence de détails sur les gemmes ou d’API facultatives.",
    ["wn_410_minimap_tracking"] = "Modification — Le menu de pistage personnalisé passe à deux colonnes, avec des lignes encadrées, un fond plus sombre, des icônes agrandies et des indicateurs cyan pour les filtres actifs. Les filtres disponibles et la fusion des doublons sont conservés ; les longues listes restent défilables.",
    ["wn_410_minimap_coords"] = "Correction — Les coordonnées natives de Blizzard sont masquées lorsque le panneau d’informations TomoMod est activé, évitant un doublon sur l’horloge, même lorsque Blizzard tente de les réafficher.",
    ["wn_410_benchmark_native_dps"] = "Modification — Le benchmark capture le DPS moyen natif du combat en cours à 30/60/120 secondes, avec la dernière valeur reçue si aucune mise à jour n’arrive après une courte attente. Le total des dégâts n’est plus affiché.",
    ["wn_410_benchmark_protected_history"] = "Nouveauté — Le DPS protégé reste visible jusqu’au rechargement. Les détails du test sont sauvegardés sans la valeur protégée ; les essais protégés récents apparaissent au-dessus du classement avec un astérisque et indiquent Protégé après rechargement.",
    ["wn_410_benchmark_cancellation"] = "Correction — Le test est annulé si le combat se termine trop tôt ou si le compteur est réinitialisé. L’absence de DPS natif est signalée au lieu d’afficher un faux zéro.",
    ["wn_410_window_fit"] = "Correction — La fenêtre d’options adapte sa taille et ses limites de redimensionnement à l’écran et à l’échelle de l’interface pour garder le pied de page et la poignée accessibles. Les en-têtes répétés ont été retirés pour libérer de l’espace.",
    ["wn_410_readability"] = "Modification — Les textes secondaires, aides et résultats de recherche sont plus contrastés, avec des caractères agrandis dans plusieurs contrôles et cartes.",
    ["wn_410_home_resets"] = "Modification — L’Accueil place les Studios juste sous le résumé et conserve Installeur et Recharger en actions rapides. La réinitialisation complète se trouve uniquement dans Profils > Réinitialisations ; les réinitialisations de modules utilisent des boutons rouges et demandent confirmation avec des indications de restauration.",
    ["wn_410_automation_movers"] = "Modification — Les interrupteurs d’automatisation décrivent leur action et l’aide de la seconde barre de statut apparaît au survol. Les anciens raccourcis de déplacement des sacs et des expéditions ont été retirés ; Sacs V4 reste la fenêtre de sacs déplaçable.",
    ["wn_410_sidebar"] = "Nouveauté — La barre latérale garde les sections principales visibles, déplie les pages Interface et Confort sur place et donne accès à chaque Studio. Elle conserve sa position de défilement ; la recherche révèle aussi les sous-pages correspondantes.",
    ["wn_410_studio_routing"] = "Modification — Les anciens panneaux de réglages sont retirés. Les raccourcis de l’Accueil, les recommandations par rôle et les anciens liens ouvrent le Studio adapté. Les pages inconnues renvoient à l’Accueil ; l’apparence du gestionnaire de cooldowns Blizzard reste dans Interface.",
    ["wn_410_nameplate_controls"] = "Nouveauté — Forge astrale propose désormais la taille du marqueur de raid des nameplates et les couleurs des incantations interruptibles ou non, transférées depuis l’ancien panneau Nameplates.",
    ["wn_410_search"] = "Nouveauté — La recherche de réglages indexe désormais les pages et contrôles de Forge astrale, Groupe & Raid et Ressources & Incantation. Les résultats ouvrent le sujet et la section correspondants, font défiler le panneau jusqu’au réglage et le mettent en évidence. Les termes de recherche anglais sont aussi pris en charge sur les clients traduits.",
    ["wn_410_navigation"] = "Correction — Les menus Interface et Confort masquent les pages indisponibles sur le client, retirent les groupes vides et gèrent les pages mémorisées.",
    ["wn_410_help"] = "Modification — Le guide explique désormais la recherche dans les options et les Studios, les onglets et l’accès direct aux Studios. L’étape obsolète sur le filtre de rôle a été retirée.",
    ["wn_410_localization"] = "Nouveauté — Les points d’ancrage et davantage de textes sont traduits dans les six langues : barres d’action, canaux audio, sauvegardes, réinitialisations, état du tableau de bord et infobulles des CVars.",
    ["wn_410_studios"] = "Correction — Les erreurs de lancement des Studios et les instructions de dépannage sont traduites. Les badges de rôle incorrects ont été retirés des en-têtes de Forge astrale, Groupe & Raid et Ressources & Incantation.",
    ["wn_410_sliders"] = "Modification — Les infobulles des curseurs distinguent le retour à la valeur par défaut du retour à la valeur à l’ouverture de la page. Les libellés anglais du son de Bloodlust et les textes du tableau de bord ont été corrigés.",
    ["wn_410_role_links"] = "Modification — Les recommandations par rôle ouvrent directement la section du Studio concernée et mettent le réglage visé en évidence. Les filtres de rôle de la barre latérale et l’action de filtrage par rôle ont été retirés ; les guides Rôles restent disponibles.",
    ["wn_410_search_groups"] = "Nouveauté — Les titres des groupes d’options sont recherchables pour retrouver plus facilement des groupes comme l’acceptation automatique des invocations. Les résultats des Studios indiquent le chemin de leur page et évitent les doublons.",
})

TomoMod_RegisterLocale("deDE", {
    ["wn_410_bags_money"] = "Behoben — Taschen zeigen Gold, Silber und Kupfer jetzt mit Münzsymbolen über die aktuelle Währungs-API an, statt bei fehlender alter Formatierungsfunktion den unformatierten Kupfergesamtbetrag auszugeben.",
    ["wn_410_loots_devourer"] = "Behoben — Die dritte Dämonenjäger-Spezialisierung ist jetzt zusätzlich zu Verwüstung und Rachsucht in Loots auswählbar und verwendet die vorhandenen Beutefilter für Spezialisierungen.",
    ["wn_410_loots_filters"] = "Neu — Loots speichert einen Ausrüstungsplatzfilter für Dungeons, Schlachtzüge und Favoriten. Angelegte Gegenstände erhalten ein grünes Häkchen; Strg-Klick öffnet die Anprobe, Umschalt-Klick fügt den Link in den aktiven Chat ein und Links- oder Rechtsklick schaltet den Favoriten um.",
    ["wn_410_loots_kithix"] = "Neu — Kith'ix bietet 12 Gegenstände im Schlachtzugsbrowser sowie auf Normal und Heroisch, dazu ein weiteres Sammelobjekt auf Mythisch. Klassen- und Spezialisierungsfilter sowie die Aufwertungsboni auf Rang 3 sind enthalten.",
    ["wn_410_loots_levels"] = "Behoben — Schlachtzugsbeutelinks verwenden jetzt Saison-17-Boni und Gegenstandsstufenanpassungen. Dungeons bieten eine gespeicherte Auswahl von M0 und M+2–M+10 für Abschlussbeute mit sofortiger Aktualisierung. Favoriten behalten ihren gespeicherten Aufwertungsbonus.",
    ["loots_all_slots"] = "Alle Ausrüstungsplätze",
    ["loots_equipped"] = "Bereits angelegt; die Aufwertungsstufe kann abweichen",
    ["loots_click_help"] = "Klick: Favorit · Umschalt-Klick: Chat · Strg-Klick: Anprobe",
    ["wn_410_character_gems"] = "Behoben — CharacterSkin liest Edelsteine jetzt über die modernen Gegenstands-APIs aus. Dadurch wird ein Initialisierungsfehler bei fehlendem GetItemGem verhindert. Charakter- und Betrachtenfenster bleiben mit älteren Clients kompatibel und verarbeiten fehlende Edelsteindaten oder optionale APIs sicher.",
    ["wn_410_minimap_tracking"] = "Änderung — Das eigene Aufspürmenü verwendet jetzt zwei Spalten, umrandete Zeilen, einen dunkleren Hintergrund, größere Symbole und türkise Anzeigen für aktive Filter. Verfügbare Filter und zusammengefasste doppelte Einträge bleiben erhalten; lange Listen lassen sich weiterhin scrollen.",
    ["wn_410_minimap_coords"] = "Behoben — Blizzards Minikartenkoordinaten werden ausgeblendet, solange das TomoMod-Infopanel aktiviert ist. Dadurch überlagern doppelte Koordinaten nicht mehr die Uhr, auch wenn Blizzard sie erneut einblendet.",
    ["wn_410_benchmark_native_dps"] = "Geändert — Der Benchmark erfasst die nativen durchschnittlichen DPS des aktuellen Kampfes nach 30/60/120 Sekunden. Fehlt nach kurzer Wartezeit eine neue Aktualisierung, wird der letzte Wert verwendet. Der Gesamtschaden wird nicht mehr angezeigt.",
    ["wn_410_benchmark_protected_history"] = "Neu — Geschützte DPS bleiben bis zum Neuladen sichtbar. Versuchsdaten werden ohne den geschützten Zahlenwert gespeichert; neueste geschützte Versuche stehen mit einem Sternchen über gewerteten Ergebnissen und zeigen nach dem Neuladen Geschützt.",
    ["wn_410_benchmark_cancellation"] = "Behoben — Tests werden bei vorzeitigem Kampfende oder Zurücksetzen des Schadensmessers abgebrochen. Fehlende native DPS werden gemeldet, statt eine falsche Null anzuzeigen.",
    ["wn_410_window_fit"] = "Behoben — Das Optionsfenster passt Größe und Größenlimits an Bildschirm und Oberflächenskalierung an, damit Fußzeile und Größenregler erreichbar bleiben. Doppelte Seitenüberschriften wurden entfernt, um Platz zu schaffen.",
    ["wn_410_readability"] = "Geändert — Sekundärtexte, Hinweise und Suchergebnisse haben mehr Kontrast; mehrere Bedienelemente und Dashboard-Karten verwenden größere Schrift.",
    ["wn_410_home_resets"] = "Geändert — Die Startseite zeigt Studios direkt unter der Übersicht und behält Installer und Neuladen als Schnellaktionen. Vollständiges Zurücksetzen ist nur unter Profile > Zurücksetzen verfügbar; Modulzurücksetzungen haben rote Schaltflächen und verlangen eine Bestätigung mit Hinweisen zur Wiederherstellung.",
    ["wn_410_automation_movers"] = "Geändert — Automatisierungsschalter beschreiben ihre Aktion ausdrücklich; die Erklärung zur zweiten Statusleiste erscheint beim Darüberfahren. Veraltete Verschieberouten für Taschen und Weltquests wurden entfernt; Taschen V4 bleibt das verschiebbare Taschenfenster.",
    ["wn_410_sidebar"] = "Neu — Die Seitenleiste hält alle Hauptbereiche sichtbar, klappt Interface- und Komfortseiten direkt auf und bietet Zugang zu jedem Studio. Die Scrollposition bleibt erhalten; die Suche zeigt auch passende Unterseiten.",
    ["wn_410_studio_routing"] = "Geändert — Die alten Einstellungsseiten wurden entfernt. Startseiten-Kürzel, Rollenempfehlungen und alte Einstellungslinks öffnen das passende Studio. Unbekannte Seiten führen zur Startseite; das Aussehen von Blizzards Abklingzeitmanager bleibt unter Interface einstellbar.",
    ["wn_410_nameplate_controls"] = "Neu — Astral Forge enthält jetzt die Größe der Schlachtzugsmarkierung auf Namensplaketten sowie Farben für unterbrechbare und nicht unterbrechbare Zauberleisten, übernommen aus der alten Namensplakettenseite.",
    ["wn_410_search"] = "Neu — Die Einstellungssuche erfasst jetzt Seiten und Bedienelemente in Astral Forge, Party & Raid Studio und Resource & Cast Studio. Treffer öffnen das passende Ziel und den richtigen Abschnitt, scrollen zur Einstellung und heben sie hervor. Englische Suchbegriffe werden auch auf übersetzten Clients unterstützt.",
    ["wn_410_navigation"] = "Behoben — Die Navigation für Interface und Komfort blendet auf dem Client nicht verfügbare Seiten aus, entfernt leere Gruppen und berücksichtigt gespeicherte Seiten sicher.",
    ["wn_410_help"] = "Geändert — Die Hilfe erklärt jetzt die Suche in Optionen und Studios, Seitenreiter und den direkten Studio-Zugang. Der veraltete Schritt zum Rollenfilter wurde entfernt.",
    ["wn_410_localization"] = "Neu — Einheitliche Ankerbezeichnungen und weitere Oberflächentexte sind in sechs Sprachen übersetzt: Aktionsleisten, Audiokanäle, Sicherungen, Modulzurücksetzungen, Dashboard-Status und CVar-Tooltips.",
    ["wn_410_studios"] = "Behoben — Startfehler der Studios und Hinweise zur Fehlerbehebung sind übersetzt. Falsche Rollensymbole wurden aus den Abschnittsüberschriften von Astral Forge, Party & Raid und Resource & Cast entfernt.",
    ["wn_410_sliders"] = "Geändert — Regler-Tooltips unterscheiden zwischen dem Standardwert und dem Wert beim Öffnen der Seite. Englische Kampfrausch-Soundtexte und Dashboard-Texte wurden korrigiert.",
    ["wn_410_role_links"] = "Geändert — Rollenempfehlungen öffnen direkt den passenden Studio-Abschnitt und heben die Zieleinstellung hervor. Die Rollenfilter der Seitenleiste und die Aktion zum Rollenfokus wurden entfernt; die Rollenleitfäden bleiben verfügbar.",
    ["wn_410_search_groups"] = "Neu — Beschriftungen von Optionsgruppen sind durchsuchbar, damit Gruppen wie die automatische Beschwörungsannahme leichter zu finden sind. Studio-Treffer zeigen ihren Seitenpfad und vermeiden doppelte Einträge.",
})

TomoMod_RegisterLocale("esES", {
    ["wn_410_bags_money"] = "Corrección — Las bolsas muestran oro, plata y cobre con sus iconos mediante la API actual de monedas, en lugar del total sin formato en cobre cuando la antigua función no está disponible.",
    ["wn_410_loots_devourer"] = "Corrección — La tercera especialización del cazador de demonios ya se puede seleccionar junto a Devastación y Venganza en Loots, utilizando los filtros de botín por especialización existentes.",
    ["wn_410_loots_filters"] = "Novedad — Loots recuerda un filtro por ranura para mazmorras, bandas y favoritos. Una marca verde indica los objetos equipados; Ctrl-clic permite probarlos, Mayús-clic inserta el enlace en el chat activo y el clic izquierdo o derecho cambia su estado de favorito.",
    ["wn_410_loots_kithix"] = "Novedad — La tabla de Kith'ix incluye 12 objetos en buscador de bandas, Normal y Heroico, más un coleccionable adicional en Mítico, con filtros de clase y especialización y los bonificadores de mejora de rango 3 del jefe.",
    ["wn_410_loots_levels"] = "Corrección — Los enlaces de botín de banda usan los bonificadores de la temporada 17 y ajustes de nivel de objeto. Las mazmorras tienen un selector guardado M0 / M+2–M+10 para el botín final, con actualización inmediata. Los favoritos conservan su bonificador guardado.",
    ["loots_all_slots"] = "Todas las ranuras",
    ["loots_equipped"] = "Ya equipado; el nivel de mejora puede variar",
    ["loots_click_help"] = "Clic: favorito · Mayús-clic: chat · Ctrl-clic: probar",
    ["wn_410_character_gems"] = "Corrección — CharacterSkin ahora lee las gemas mediante las API modernas de objetos, evitando un error de inicialización cuando GetItemGem no está disponible. Las ventanas de personaje e inspección mantienen la compatibilidad con clientes antiguos y gestionan la ausencia de datos de gemas o de API opcionales.",
    ["wn_410_minimap_tracking"] = "Cambio — El menú de rastreo personalizado ahora usa dos columnas, filas con borde, un fondo más oscuro, iconos más grandes e indicadores cian para los filtros activos. Se conservan los filtros disponibles y la agrupación de duplicados; las listas largas siguen permitiendo desplazarse.",
    ["wn_410_minimap_coords"] = "Corrección — Las coordenadas nativas de Blizzard se ocultan mientras el panel de información de TomoMod está activado, evitando que las coordenadas duplicadas se superpongan al reloj, incluso si Blizzard intenta mostrarlas de nuevo.",
    ["wn_410_benchmark_native_dps"] = "Cambio — El benchmark captura el DPS medio nativo del combate actual a los 30/60/120 segundos. Si no llega una nueva actualización tras una breve espera, usa el último valor. Ya no se muestra el daño total.",
    ["wn_410_benchmark_protected_history"] = "Novedad — El DPS protegido permanece visible hasta recargar. Se guardan los detalles del intento sin el número protegido; los intentos protegidos recientes aparecen encima de los resultados clasificados con un asterisco y muestran Protegido tras recargar.",
    ["wn_410_benchmark_cancellation"] = "Corrección — Las pruebas se cancelan si el combate termina antes de tiempo o se reinicia el medidor. La ausencia de DPS nativo se indica en lugar de mostrar un cero falso.",
    ["wn_410_window_fit"] = "Corrección — La ventana de opciones adapta su tamaño y sus límites a la pantalla y a la escala de la interfaz, manteniendo accesibles el pie y el control de tamaño. Se eliminaron los encabezados repetidos para ganar espacio.",
    ["wn_410_readability"] = "Cambio — Los textos secundarios, las ayudas y los resultados de búsqueda tienen más contraste, con letras más grandes en varios controles y tarjetas.",
    ["wn_410_home_resets"] = "Cambio — Inicio coloca los Studios justo debajo del resumen y conserva Instalador y Recargar como acciones rápidas. El reinicio completo solo está en Perfiles > Restablecer; los reinicios de módulos usan botones rojos y piden confirmación con instrucciones de recuperación.",
    ["wn_410_automation_movers"] = "Cambio — Los interruptores de automatización describen su acción y la ayuda de la segunda barra de estado aparece al pasar el cursor. Se eliminaron las rutas antiguas de movimiento de bolsas y misiones del mundo; Bolsas V4 sigue siendo la ventana de bolsas móvil.",
    ["wn_410_sidebar"] = "Novedad — La barra lateral mantiene visibles las secciones principales, despliega las páginas de Interfaz y Comodidad y permite acceder a cada Studio. Conserva la posición de desplazamiento; la búsqueda también muestra las subpáginas coincidentes.",
    ["wn_410_studio_routing"] = "Cambio — Se retiran los antiguos paneles de ajustes. Los atajos de Inicio, las recomendaciones por rol y los enlaces antiguos abren el Studio correspondiente. Las páginas desconocidas llevan a Inicio; la apariencia del gestor de reutilización de Blizzard sigue en Interfaz.",
    ["wn_410_nameplate_controls"] = "Novedad — Astral Forge incluye ahora el tamaño del marcador de banda en las placas de nombre y los colores de lanzamiento interrumpible o no interrumpible, trasladados desde el antiguo panel de placas.",
    ["wn_410_search"] = "Novedad — La búsqueda de ajustes ahora indexa páginas y controles de Astral Forge, Party & Raid Studio y Resource & Cast Studio. Los resultados abren el elemento y la sección correspondientes, desplazan el panel hasta el ajuste y lo resaltan. También se admiten términos de búsqueda en inglés en clientes traducidos.",
    ["wn_410_navigation"] = "Corrección — La navegación de Interfaz y Comodidad oculta las páginas no disponibles en el cliente, elimina los grupos vacíos y gestiona las páginas recordadas de forma segura.",
    ["wn_410_help"] = "Cambio — La guía explica la búsqueda en opciones y Studios, las pestañas y el acceso directo a los Studios. Se ha eliminado el paso obsoleto sobre el filtro de rol.",
    ["wn_410_localization"] = "Novedad — Los nombres de los anclajes y más textos están traducidos a seis idiomas: barras de acción, canales de audio, copias de seguridad, reinicios de módulos, estado del panel e información de CVars.",
    ["wn_410_studios"] = "Corrección — Los errores al abrir Studios y las instrucciones para resolverlos están traducidos. Se eliminaron los indicadores de rol incorrectos de los encabezados de Astral Forge, Party & Raid y Resource & Cast.",
    ["wn_410_sliders"] = "Cambio — Las ayudas de los deslizadores distinguen entre restaurar el valor predeterminado y volver al valor que había al abrir la página. Se corrigieron los textos en inglés del sonido de Ansia de sangre y del panel de inicio.",
    ["wn_410_role_links"] = "Cambio — Las recomendaciones por rol abren directamente la sección correspondiente del Studio y resaltan el ajuste. Se han eliminado los filtros de rol de la barra lateral y la acción de enfoque por rol; las guías de Roles siguen disponibles.",
    ["wn_410_search_groups"] = "Novedad — Los títulos de los grupos de opciones se pueden buscar para encontrar más fácilmente grupos como la aceptación automática de invocaciones. Los resultados de Studios muestran la ruta de su página y evitan entradas duplicadas.",
